Recall our Top 10 example:
This code gave a list of 10 Aboriginal Languages which have the most number of people who speak them as their mother tongue:

# code for top 10 aboriginal languages
ten_lang &lt;- can_lang |&gt;
  filter(category == "Aboriginal languages") |&gt;
  arrange(desc(mother_tongue)) |&gt;
  slice(1:10)

Schiny
This is just some example code. We’re not going to run this. I’m going to show you an example from students I had during J-term.


Code
library(shiny)
library(ggplot2)
library(dplyr)
library(palmerpenguins)

ui &lt;- fluidPage(
  selectInput("species", "Species:",
              choices = c("All", unique(na.omit(penguins$species)))),
  plotOutput("plot")
)

server &lt;- function(input, output) {

  filtered &lt;- reactive({
    if (input$species == "All") penguins
    else filter(penguins, species == input$species)
  })

  output$plot &lt;- renderPlot({
    ggplot(filtered(),
           aes(bill_length_mm, flipper_length_mm, color = species)) +
      geom_point() +
      theme_minimal()
  })
}

shinyApp(ui, server)

summarize() or summarise() (either works)
Suppose we are interested in the average bill length of all Adelie penguins.

# use summarize for average bill length in Adelie penguins
# Do it first without removing NAs

penguins |&gt;
  filter(species=="Adelie") |&gt;
  summarize(mean(bill_length_mm))

# A tibble: 1 × 1
  `mean(bill_length_mm)`
                   &lt;dbl&gt;
1                     NA

# have to deal with the NAs

penguins |&gt;
  filter(species=="Adelie") |&gt;
  summarize(mean(bill_length_mm, na.rm=TRUE))

# A tibble: 1 × 1
  `mean(bill_length_mm, na.rm = TRUE)`
                                 &lt;dbl&gt;
1                                 38.8

# Then remove NAs using na.rm=TRUE


penguins |&gt;
  filter(species=="Adelie") |&gt;
  drop_na(bill_length_mm)  |&gt;
  summarize(mean(bill_length_mm))

# A tibble: 1 × 1
  `mean(bill_length_mm)`
                   &lt;dbl&gt;
1                   38.8

penguins |&gt;
  filter(species=="Adelie") |&gt;
  drop_na() |&gt;
  summarize(mean(bill_length_mm))

# A tibble: 1 × 1
  `mean(bill_length_mm)`
                   &lt;dbl&gt;
1                   38.8


Suppose we are interested in the average bill length AND average bill depth of all Adelie penguins:

# calculate average bill length and average bill depth for Adelie
# filter for Adelie then summarize

penguins |&gt;
  filter(species=="Adelie") |&gt;
  summarize(mean(bill_length_mm, na.rm=TRUE),
            mean(bill_depth_mm, na.rm=TRUE))

# A tibble: 1 × 2
  `mean(bill_length_mm, na.rm = TRUE)` `mean(bill_depth_mm, na.rm = TRUE)`
                                 &lt;dbl&gt;                               &lt;dbl&gt;
1                                 38.8                                18.3


There are lots of other functions available:

min: minimum value
max: maximum value
mean: average or mean value
median: median value
var: variance
sd: standard deviation
n: count or number of values
n_distinct: counts number of distinct values

Suppose we are interested in the average bill length AND the median bill length of all Adelie penguins:

# filter for Adelie and summarise (but change to median)
# average bill length and MEDIAN bill length

penguins |&gt;
  filter(species=="Adelie") |&gt;
  summarize(mean(bill_length_mm, na.rm=TRUE),
            median(bill_length_mm, na.rm=TRUE),
            n())

# A tibble: 1 × 3
  `mean(bill_length_mm, na.rm = TRUE)` median(bill_length_mm, na.rm = TR…¹ `n()`
