1                                 38.8                                38.8   152
# ℹ abbreviated name: ¹​`median(bill_length_mm, na.rm = TRUE)`

penguins |&gt;
  filter(species=="Adelie") |&gt;
  drop_na(bill_length_mm) |&gt;
